insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_pe2_v1'
from (values
('116.63.c.1.A',2,'A new hiker learns to read a trail map and use a compass. This is an example of building what?','["A basic skill for outdoor navigation", "An advanced racing technique", "A swimming stroke", "A team sport rule"]'::jsonb,0,'Map and compass use is a basic outdoor skill.','original'),
('116.63.c.1.A',2,'Which is a basic skill in recreational paddling?','["Throwing a javelin", "Using a forward stroke to move a canoe in a straight line", "Serving a tennis ball", "Spiking a volleyball"]'::jsonb,1,'A forward stroke is a core paddling skill.','original'),
('116.63.c.1.B',3,'At a disc golf course, a player must throw from behind the tee line and play the disc where it lands. This is an example of what?','["Using no equipment", "Skipping the strategy", "Following the rules of the activity", "Breaking an etiquette rule"]'::jsonb,2,'Rules set how play proceeds.','original'),
('116.63.c.1.B',3,'On a windy day, a golfer chooses a lower, flatter shot to keep the ball from drifting. This is an example of what?','["Avoiding practice", "Skipping the warm-up", "Ignoring the rules", "Applying strategy to conditions"]'::jsonb,3,'Strategy adapts to the environment.','original'),
('116.63.c.1.C',3,'A person training for a weekend backpacking trip builds a plan with hill walks, a loaded pack and leg strength work. What is this?','["A conditioning program matched to the activity", "A rest-only plan", "A cooking plan", "A random list"]'::jsonb,0,'Conditioning is tailored to the demands of the activity.','original'),
('116.63.c.1.C',3,'A kayaker designs a conditioning program. Which fitness area should it most emphasize?','["Only balance on a beam", "Upper-body and core endurance", "Only leg flexibility", "Only reaction time"]'::jsonb,1,'Paddling relies on the upper body and core.','original'),
('116.63.c.2.A',3,'A rock climber sees her foot slipping and moves her weight over it, then adjusts her grip. This shows what?','["Random movement", "Ignoring feedback", "Modifying movement using internal feedback", "Only external feedback"]'::jsonb,2,'Body sensations guide adjustments.','original'),
('116.63.c.2.A',3,'A guide tells a beginner to keep her hands wider on the paddle. Using the tip is which type of feedback?','["No feedback", "Internal feedback only", "Delayed feedback only", "External feedback"]'::jsonb,3,'Information from another person is external.','original'),
('116.63.c.2.B',3,'Which is a critical element of a successful cast in fishing?','["Smooth release timing and a controlled follow-through", "Using no line", "Closing your eyes", "Throwing as hard as possible"]'::jsonb,0,'Timing and follow-through control the cast.','original'),
('116.63.c.2.B',3,'In archery, which critical element helps accuracy?','["Changing grip every shot", "A consistent stance and steady anchor point", "Ignoring the target", "Rushing each shot"]'::jsonb,1,'Consistency improves accuracy.','original'),
('116.63.c.3.A',2,'Which outdoor pursuit provides enjoyment along with health benefits?','["Skipping activity", "Sitting indoors all day", "Hiking on a trail with friends", "Watching a screen"]'::jsonb,2,'Hiking offers enjoyment and activity.','original'),
('116.63.c.3.A',2,'Why do people choose lifetime activities such as cycling or swimming?','["They end at graduation", "They can only be done once", "They require a team of ten", "They can be enjoyed throughout life for fitness and fun"]'::jsonb,3,'Lifetime activities last across ages.','original'),
('116.63.c.3.B',3,'To improve flexibility for hiking and climbing, a person should perform what?','["Regular stretching held for 15 to 30 seconds after warming up", "Bouncing stretches while cold", "Only running", "Skipping stretching"]'::jsonb,0,'Held stretches after a warm-up improve flexibility.','original'),
('116.63.c.3.B',3,'Which training principle states that muscle needs gradually increasing resistance to grow stronger?','["Detraining", "Progressive overload", "Rest day only", "Cooling down only"]'::jsonb,1,'Gradual loading improves strength.','original'),
('116.63.c.3.C',3,'Which fitness goal is realistic and challenging?','["Run a marathon tomorrow", "Improve someday", "Hike 5 miles without stopping within six weeks of regular walks", "Never exercise"]'::jsonb,2,'A good goal is measurable and reachable.','original'),
('116.63.c.3.C',3,'Why should health-related fitness goals be written with a time frame?','["So the goal is harder to track", "To hide results", "To avoid effort", "So progress can be measured and the plan adjusted"]'::jsonb,3,'Time frames make goals measurable.','original'),
('116.63.c.3.D',3,'A hiker uses a GPS watch to track distance and elevation. What is this technology used for?','["Monitoring activity to evaluate and improve fitness", "Replacing fitness", "Predicting injuries only", "Controlling the weather"]'::jsonb,0,'Trackers provide data to evaluate progress.','original'),
('116.63.c.3.D',3,'Which tool can display heart rate while exercising outdoors?','["A flashlight", "A heart rate monitor", "A compass", "A thermometer"]'::jsonb,1,'A heart rate monitor shows intensity.','original'),
('116.63.c.3.E',3,'Regular cycling can improve which fitness area?','["Only reading skills", "Only reaction time", "Cardiorespiratory endurance and leg strength", "Only hand speed"]'::jsonb,2,'Cycling works the heart, lungs and legs.','original'),
('116.63.c.3.E',3,'Which is a health benefit of regular outdoor recreation?','["Lower fitness", "Less sleep always", "More stress only", "Lower stress and improved fitness"]'::jsonb,3,'Outdoor activity benefits body and mind.','original'),
('116.63.c.3.F',3,'A personal fitness program for outdoor pursuits should include what?','["Goals, planned activities, progress checks and rest", "No plan", "Only snacks", "Only one workout"]'::jsonb,0,'A program sets goals and tracks progress.','original'),
('116.63.c.3.F',3,'A student begins a four-week program of walking, bodyweight strength work and stretching. What should come next in the program cycle?','["Stop tracking", "Evaluate results and adjust the plan", "Start over with no data", "Quit"]'::jsonb,1,'Evaluation guides adjustments.','original'),
('116.63.c.4.A',3,'Two hikers share the navigation and decision making on a long trail. This shows what teamwork skill?','["Competition only", "Avoidance", "Cooperation and shared problem solving", "Isolation"]'::jsonb,2,'Teams share tasks and decisions.','original'),
('116.63.c.4.A',3,'A group on a ropes course helps each other through an obstacle. Which skill is demonstrated?','["Silence only", "Selfishness", "Ignoring teammates", "Trust and support"]'::jsonb,3,'Trust and support build teams.','original'),
('116.63.c.4.B',3,'At a campsite, which behavior shows good outdoor etiquette?','["Keeping noise low and leaving the site clean", "Leaving trash", "Playing music loudly all night", "Cutting new trails"]'::jsonb,0,'Etiquette respects others and nature.','original'),
('116.63.c.4.B',3,'A cyclist on a shared trail should do what when approaching a walker from behind?','["Speed up silently", "Announce the pass and slow down", "Ignore the walker", "Ride on the grass"]'::jsonb,1,'Courtesy keeps shared trails safe.','original'),
('116.63.c.4.C',3,'A student replaces hours of screen scrolling with a daily walk and feels calmer. What does this show?','["Mood never changes", "Screens never matter", "Technology use can affect mood and activity levels", "Walking is harmful"]'::jsonb,2,'Habits affect social and emotional health.','original'),
('116.63.c.4.C',3,'Which is a possible positive use of technology for outdoor activity?','["Replacing all exercise", "Hiding from others", "Ignoring safety", "Using a map app to find trails and share plans with friends"]'::jsonb,3,'Technology can support healthy habits.','original'),
('116.63.c.4.D',3,'A student reads an article on how time in nature affects mood and summarizes the main points. This shows which skill?','["Analyzing and summarizing critical information", "Ignoring sources", "Copying", "Guessing"]'::jsonb,0,'Summarizing shows understanding of the research.','original'),
('116.63.c.4.D',3,'Which source would be best for information about the mental health benefits of outdoor activity?','["An anonymous post", "A peer-reviewed study or a health agency", "A rumor", "A product ad"]'::jsonb,1,'Credible sources provide reliable evidence.','original'),
('116.63.c.4.E',3,'A personal wellness plan that includes outdoor pursuits might schedule what?','["No activity", "Only snacks", "Weekly time outside for hiking, biking or paddling", "Only screen time"]'::jsonb,2,'A wellness plan sets regular activity.','original'),
('116.63.c.4.E',3,'Which part of a wellness plan supports emotional health?','["Skipping sleep", "Isolation", "Ignoring stress", "Spending time outdoors with supportive people"]'::jsonb,3,'Social time outdoors supports emotional health.','original'),
('116.63.c.5.A',2,'Which is required safety equipment for riding a bicycle on a trail?','["A properly fitted helmet", "Sandals", "A heavy backpack", "Headphones turned up loud"]'::jsonb,0,'A helmet protects the head.','original'),
('116.63.c.5.A',2,'A person paddling a kayak should wear what?','["Heavy boots", "A personal flotation device", "A winter coat only", "A blindfold"]'::jsonb,1,'A life jacket prevents drowning.','original'),
('116.63.c.5.B',3,'Before a hike a person should file a plan with someone, which means what?','["Hiding the route", "Telling no one", "Telling a trusted person the route and expected return time", "Leaving without water"]'::jsonb,2,'Someone can raise an alarm if you do not return.','original'),
('116.63.c.5.B',3,'If a thunderstorm approaches while hiking in the open, the safest procedure is to do what?','["Stand on a hilltop", "Hold a metal pole up", "Stand under the tallest tree", "Move to lower ground or shelter and avoid isolated tall objects"]'::jsonb,3,'Avoid exposed high spots in lightning.','original'),
('116.63.c.5.C',3,'Which fitness principle applies when a hiker gradually increases trail distance each week?','["Progression", "Rest", "Specificity", "Reversibility"]'::jsonb,0,'Gradual increases are progression.','original'),
('116.63.c.5.C',3,'The FITT principle stands for frequency, intensity, time and what?','["Tempo", "Type", "Test", "Terrain"]'::jsonb,1,'Type is the T that follows time.','original'),
('116.63.c.5.D',3,'After a day of hiking, a person''s body needs sleep because sleep does what?','["Reduces strength", "Removes fitness", "Supports muscle repair and restores energy", "Slows recovery"]'::jsonb,2,'Recovery occurs during sleep.','original'),
('116.63.c.5.D',3,'A camper stays up all night and tries a long bike ride in the morning. What is the likely outcome?','["More energy", "Faster reactions", "Better performance", "Lower performance and higher injury risk"]'::jsonb,3,'Sleep loss harms performance and safety.','original'),
('116.63.c.5.E',3,'Which is an advantage of outdoor recreation compared with a gym workout?','["Natural scenery and varied terrain", "Guaranteed perfect weather", "No travel ever", "No cost ever"]'::jsonb,0,'Outdoor activity offers variety.','original'),
('116.63.c.5.E',3,'Which is a disadvantage of some outdoor pursuits?','["Always indoors", "Weather, travel and equipment costs", "Always free", "No risks at all"]'::jsonb,1,'Outdoor pursuits have tradeoffs.','original'),
('116.63.c.5.F',3,'A student records mile times each week for two months and sees them drop. This provides what?','["No evidence", "Proof of injury", "Evidence of improved health-related fitness", "A lower grade"]'::jsonb,2,'Data show progress.','original'),
('116.63.c.5.F',3,'Which is evidence that a person is maintaining fitness?','["Random guesses", "Skipping workouts", "No data", "Consistent test results and regular activity logs"]'::jsonb,3,'Consistent data show maintenance.','original'),
('116.63.c.5.G',3,'A climber designs a safe practice routine by starting on easy routes with a belay partner and moving up gradually. What does this show?','["A safe, progressive way to improve skill", "A random approach", "Climbing alone at height", "Skipping safety"]'::jsonb,0,'Safe progression reduces risk.','original'),
('116.63.c.5.G',3,'Which practice procedure is safest for improving a new skill?','["Skip instruction", "Learn with supervision and increase difficulty gradually", "Practice alone in danger", "Try the hardest version first"]'::jsonb,1,'Gradual, supervised practice is safest.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
